        --surface-2: #151d2d;
        --surface-3: #1c2638;
        --text: #f5f7fb;
        --muted: #c4cedd;
        --soft: #95a3b8;
        --accent: #ffd166;
        --accent-strong: #ffbd2e;
        --accent-dark: #3a2600;
        --teal: #77e4d4;
        --rose: #ff8fab;
        --border: #354157;
        --focus: #8ee8ff;
        --shadow: #000000;
        --max-width: 1180px;
        --radius-lg: 28px;
        --radius-md: 18px;
        --radius-sm: 12px;
      }

      * {
        box-sizing: border-box;
      }

      html {
        scroll-behavior: smooth;
      }

      body {
        margin: 0;
        min-width: 320px;
        background:
          radial-gradient(circle at top left, #213355 0, transparent 34rem),
          radial-gradient(circle at 84% 12%, #42233f 0, transparent 28rem),
          var(--bg);
        color: var(--text);
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        line-height: 1.5;
      }

      a {
        color: inherit;
      }

      img,
      svg {
        max-width: 100%;
      }

      button,
      input {
        font: inherit;
      }

      :focus-visible {
        outline: 3px solid var(--focus);
        outline-offset: 4px;
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 10;
        transform: translateY(-160%);
        border-radius: 999px;
        background: var(--accent);
        color: #101010;
        font-weight: 800;
        padding: 0.75rem 1rem;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .page-shell {
        width: min(100% - 2rem, var(--max-width));
        margin-inline: auto;
      }

      .site-header {
        position: sticky;
        top: 0;
        z-index: 5;
        border-bottom: 1px solid var(--border);
        background: #080b12;
        box-shadow: 0 18px 40px var(--shadow);
      }

      .header-inner {
        display: flex;
        min-height: 76px;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
      }

      .brand {
        display: inline-flex;
        align-items: center;
        gap: 0.7rem;
        min-width: 0;
        text-decoration: none;
      }

      .brand-mark {
        display: grid;
        width: 2.5rem;
        height: 2.5rem;
        flex: 0 0 auto;
        place-items: center;
        border: 1px solid var(--border);
        border-radius: 50%;
        background: linear-gradient(135deg, var(--accent), var(--teal));
        color: #111827;
        font-weight: 900;
      }

      .brand-name {
        font-size: clamp(1rem, 3vw, 1.2rem);
        font-weight: 900;
        letter-spacing: 0.02em;
        overflow-wrap: anywhere;
      }

      .nav-toggle {
        display: none;
        border: 1px solid var(--border);
        border-radius: 999px;
        background: var(--surface);
        color: var(--text);
        cursor: pointer;
        font-weight: 800;
        padding: 0.65rem 0.9rem;
      }

      .primary-nav ul,
      .utility-nav {
        display: flex;
        align-items: center;
        gap: 0.35rem;
        margin: 0;
        padding: 0;
        list-style: none;
      }

      .primary-nav a,
      .utility-link,
      .cart-button {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        min-height: 44px;
        border-radius: 999px;
        color: var(--muted);
        font-weight: 750;
        text-decoration: none;
        padding: 0.65rem 0.85rem;
      }

      .primary-nav a:hover,
      .utility-link:hover,
      .cart-button:hover {
        background: var(--surface-2);
        color: var(--text);
      }

      .cart-button {
        border: 1px solid var(--border);
        background: var(--surface);
        cursor: pointer;
      }

      .cart-count {
        display: inline-grid;
        min-width: 1.5rem;
        min-height: 1.5rem;
        margin-left: 0.45rem;
        place-items: center;
        border-radius: 999px;
        background: var(--accent);
        color: #101010;
        font-size: 0.85rem;
        font-weight: 900;
      }

      main {
        padding-bottom: 4rem;
      }

      .hero {
        display: grid;
        grid-template-columns: minmax(0, 1.1fr) minmax(280px, 0.9fr);
        gap: 1.5rem;
        align-items: stretch;
        padding-block: clamp(2rem, 7vw, 5rem);
      }

      .hero-copy,
      .hero-panel,
      .section-card {
        border: 1px solid var(--border);
        border-radius: var(--radius-lg);
        background: linear-gradient(145deg, #121a2a, #0e1320);
        box-shadow: 0 24px 70px var(--shadow);
      }

      .hero-copy {
        display: flex;
        flex-direction: column;
        justify-content: center;
        min-width: 0;
        padding: clamp(1.25rem, 5vw, 3rem);
      }

      .eyebrow {
        display: inline-flex;
        width: fit-content;
        align-items: center;
        gap: 0.5rem;
        border: 1px solid var(--border);
        border-radius: 999px;
        background: var(--surface-2);
        color: var(--teal);
        font-size: 0.83rem;
        font-weight: 850;
        letter-spacing: 0.09em;
        padding: 0.4rem 0.75rem;
        text-transform: uppercase;
      }

      h1,
      h2,
      h3 {
        margin: 0;
        line-height: 1.05;
      }

      h1 {
        max-width: 12ch;
        margin-top: 1.1rem;
        font-size: clamp(3rem, 10vw, 6.7rem);
        letter-spacing: -0.08em;
      }

      .hero-copy p,
      .section-intro,
      .card-copy,
      .article-card p,
      .deal-copy,
      .footer-copy {
        color: var(--muted);
      }

      .hero-copy p {
        max-width: 62ch;
        margin: 1.25rem 0 0;
        font-size: clamp(1.05rem, 2vw, 1.25rem);
      }

      .hero-actions {
        display: flex;
        flex-wrap: wrap;
        gap: 0.85rem;
        margin-top: 2rem;
      }

      .button {
        display: inline-flex;
        min-height: 48px;
        align-items: center;
        justify-content: center;
        border: 1px solid var(--border);
        border-radius: 999px;
        cursor: pointer;
        font-weight: 900;
        text-decoration: none;
        padding: 0.85rem 1.15rem;
        transition:
          transform 160ms ease,
          background-color 160ms ease;
      }

      .button:hover {
        transform: translateY(-2px);
      }

      .button-primary {
        border-color: var(--accent);
        background: var(--accent);
        color: #121212;
      }

      .button-primary:hover {
        background: var(--accent-strong);
      }

      .button-secondary {
        background: var(--surface-2);
        color: var(--text);
      }

      .hero-panel {
        display: grid;
        min-height: 560px;
        overflow: hidden;
        padding: 1rem;
      }

      .showcase {
        position: relative;
        display: grid;
        align-content: end;
        overflow: hidden;
        border-radius: 22px;
        background:
          radial-gradient(circle at 48% 20%, #ffd166 0 5.5rem, transparent 5.7rem),
          linear-gradient(150deg, #24314b, #111827 68%);
        padding: 1.25rem;
      }

      .showcase::before,
      .showcase::after {
        position: absolute;
        content: "";
        border: 1px solid #61708b;
        border-radius: 999px;
      }

      .showcase::before {
        width: 17rem;
        height: 17rem;
        right: -4rem;
        top: 4rem;
      }

      .showcase::after {
        width: 11rem;
        height: 11rem;
        left: 2rem;
        top: 8rem;
      }

      .showcase-card {
        position: relative;
        z-index: 1;
        max-width: 22rem;
        border: 1px solid var(--border);
        border-radius: var(--radius-md);
        background: #101624;
        padding: 1.25rem;
      }

      .showcase-card h2 {
        font-size: clamp(1.7rem, 4vw, 2.5rem);
      }

      .price-row {
        display: flex;
        align-items: baseline;
        gap: 0.7rem;
        margin-top: 1rem;
      }

      .price {
        color: var(--accent);
        font-size: 1.6rem;
        font-weight: 950;
      }

      .old-price {
        color: var(--soft);
        text-decoration: line-through;
      }

      section {
        scroll-margin-top: 96px;
      }

      .section-header {
        display: flex;
        align-items: end;
        justify-content: space-between;
        gap: 1rem;
        margin: 0 0 1rem;
      }

      .section-header h2 {
        font-size: clamp(2rem, 6vw, 3.5rem);
        letter-spacing: -0.05em;
      }

      .section-intro {
        max-width: 42rem;
        margin: 0.5rem 0 0;
      }

      .product-grid,
      .deal-grid,
      .editorial-grid {
        display: grid;
        gap: 1rem;
      }

      .product-grid {
        grid-template-columns: repeat(4, minmax(0, 1fr));
      }

      .product-card,
      .deal-card,
      .article-card,
      .newsletter {
        min-width: 0;
        border: 1px solid var(--border);
        border-radius: var(--radius-md);
        background: var(--surface);
      }

      .product-card {
        display: flex;
        flex-direction: column;
        overflow: hidden;
      }

      .product-art {
        display: grid;
        min-height: 220px;
        place-items: center;
        border-bottom: 1px solid var(--border);
        background: linear-gradient(145deg, var(--surface-2), var(--surface-3));
      }

      .product-orb {
        width: 9rem;
        height: 9rem;
        border: 1px solid #71809a;
        border-radius: 42% 58% 50% 50%;
        background: var(--orb);
        box-shadow: 0 24px 54px var(--shadow);
      }

      .product-body {
        display: flex;
        flex: 1;
        flex-direction: column;
        gap: 0.8rem;
        padding: 1rem;
      }

      .product-meta,
      .deal-meta {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        justify-content: space-between;
        gap: 0.5rem;
      }

      .category,
      .tag {
        color: var(--teal);
        font-size: 0.78rem;
        font-weight: 850;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      .rating {
        color: var(--accent);
        font-weight: 850;
      }

      .product-card h3,
      .deal-card h3,
      .article-card h3 {
        font-size: 1.25rem;
      }

      .product-card .button,
      .deal-card .button {
        width: 100%;
        margin-top: auto;
      }

      .deal-grid {
        grid-template-columns: 1.15fr 0.85fr;
      }

      .deal-card {
        padding: clamp(1rem, 3vw, 1.5rem);
      }

      .deal-card.featured {
        display: grid;
        grid-template-columns: minmax(0, 1fr) minmax(160px, 0.75fr);
        gap: 1rem;
        align-items: center;
        background:
          radial-gradient(circle at 84% 20%, #5b2b47 0, transparent 18rem),
          var(--surface);
      }

      .deal-card h3 {
        margin-top: 0.85rem;
        font-size: clamp(1.7rem, 4vw, 2.8rem);
        letter-spacing: -0.04em;
      }

      .deal-visual {
        min-height: 16rem;
        border: 1px solid var(--border);
        border-radius: 22px;
        background:
          linear-gradient(135deg, transparent 35%, #77e4d4 36% 40%, transparent 41%),
          radial-gradient(circle, #ffd166 0 24%, transparent 25%),
          linear-gradient(145deg, #1f2940, #111827);
      }

      .deal-stack {
        display: grid;
        gap: 1rem;
      }

      .timer {
        display: inline-flex;
        width: fit-content;
        border-radius: 999px;
        background: var(--accent-dark);
        color: var(--accent);
        font-weight: 900;
        padding: 0.45rem 0.7rem;
      }

      .editorial-grid {
        grid-template-columns: repeat(3, minmax(0, 1fr));
      }

      .article-card {
        overflow: hidden;
      }

      .article-art {
        min-height: 180px;
        border-bottom: 1px solid var(--border);
        background: var(--art);
      }

      .article-body {
        padding: 1rem;
      }

      .article-card a {
        display: inline-flex;
        min-height: 44px;
        align-items: center;
        color: var(--accent);
        font-weight: 850;
        text-decoration-thickness: 0.12em;
        text-underline-offset: 0.25em;
      }

      .newsletter {
        display: grid;
        grid-template-columns: minmax(0, 0.9fr) minmax(260px, 1fr);
        gap: 1rem;
        align-items: center;
        margin-top: 1rem;
        padding: clamp(1rem, 4vw, 1.5rem);
      }

      .newsletter h2 {
        font-size: clamp(1.8rem, 5vw, 3rem);
        letter-spacing: -0.05em;
      }

      .signup-form {
        display: grid;
        gap: 0.65rem;
      }

      .signup-form label {
        color: var(--text);
        font-weight: 850;
      }

      .input-row {
        display: flex;
        gap: 0.6rem;
      }

      .signup-form input {
        width: 100%;
        min-height: 48px;
        min-width: 0;
        border: 1px solid var(--border);
        border-radius: 999px;
        background: #080b12;
        color: var(--text);
        padding: 0.85rem 1rem;
      }

      .form-help,
      .status-message {
        color: var(--muted);
        margin: 0;
      }

      .status-message {
        min-height: 1.5rem;
        font-weight: 800;
      }

      .site-footer {
        border-top: 1px solid var(--border);
        background: #080b12;
        padding-block: 2rem;
      }

      .footer-inner {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
      }

      .footer-links {
        display: flex;
        flex-wrap: wrap;
        gap: 0.7rem;
      }

      .footer-links a {
        min-height: 44px;
        color: var(--muted);
        font-weight: 750;
        text-decoration: none;
      }

      .footer-links a:hover {
        color: var(--text);
        text-decoration: underline;
        text-underline-offset: 0.25em;
      }

      @media (prefers-reduced-motion: reduce) {
        *,
        *::before,
        *::after {
          scroll-behavior: auto !important;
          transition-duration: 0.01ms !important;
        }
      }

      @media (max-width: 960px) {
        .header-inner {
          flex-wrap: wrap;
          padding-block: 0.85rem;
        }

        .nav-toggle {
          display: inline-flex;
        }

        .primary-nav {
          display: none;
          order: 3;
          width: 100%;
        }

        .primary-nav.is-open {
          display: block;
        }

        .primary-nav ul {
          display: grid;
          gap: 0.35rem;
        }

        .primary-nav a {
          justify-content: flex-start;
          width: 100%;
        }

        .utility-nav {
          margin-left: auto;
        }

        .hero,
        .deal-grid,
        .newsletter {
          grid-template-columns: 1fr;
        }

        .product-grid,
        .editorial-grid {
          grid-template-columns: repeat(2, minmax(0, 1fr));
        }
      }

      @media (max-width: 640px) {
        .page-shell {
          width: min(100% - 1rem, var(--max-width));
        }

        .utility-link {
          display: none;
        }

        .hero-panel {
          min-height: 420px;
        }

        .section-header,
        .footer-inner,
        .input-row {
          align-items: stretch;
          flex-direction: column;
        }

        .deal-card.featured,
        .product-grid,
        .editorial-grid {
          grid-template-columns: 1fr;
        }
      }

      @media (forced-colors: active) {
        :root {
          --bg: Canvas;
          --surface: Canvas;
          --surface-2: Canvas;
          --surface-3: Canvas;
          --text: CanvasText;
          --muted: CanvasText;
          --soft: CanvasText;
          --accent: ButtonText;
          --accent-strong: ButtonText;
          --accent-dark: Canvas;
          --teal: CanvasText;
          --rose: CanvasText;
          --border: ButtonBorder;
          --focus: Highlight;
          --shadow: Canvas;
        }

        .button,
        .cart-button,
        .nav-toggle,
        .signup-form input {
          border-color: ButtonBorder;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="app"></div>

    <script>
      const products = [
        {
          name: "Astra Knit Bomber",
          category: "Outerwear",
          price: "$188",
          rating: "4.9",
          orb: "linear-gradient(135deg, #77e4d4, #24314b)",
        },
        {
          name: "Midnight Runner",
          category: "Footwear",
          price: "$142",
          rating: "4.8",
          orb: "linear-gradient(135deg, #ffd166, #5b2b47)",
        },
        {
          name: "Obsidian Carryall",
          category: "Bags",
          price: "$96",
          rating: "4.7",
          orb: "linear-gradient(135deg, #95a3b8, #101624)",
        },
        {
          name: "Lumen Rib Set",
          category: "Essentials",
          price: "$74",
          rating: "4.9",
          orb: "linear-gradient(135deg, #ff8fab, #151d2d)",
        },
      ];

      const articles = [
        {
          title: "How to build a capsule wardrobe for late nights",
          tag: "Style Notes",
          copy: "Five versatile layers that move from office hours to after-dark plans.",
          art: "linear-gradient(135deg, #182133 0 35%, #77e4d4 36% 38%, #24314b 39% 100%)",
        },
        {
          title: "Behind the material: recycled satin shells",
          tag: "Materials",
          copy: "A closer look at the low-sheen finish defining this season's outerwear.",
          art: "radial-gradient(circle at 26% 34%, #ffd166 0 22%, transparent 23%), linear-gradient(135deg, #111827, #263550)",
        },
        {
          title: "The editor's guide to gifting under $100",
          tag: "Gift Guide",
          copy: "Polished accessories, soft knits, and small luxuries worth wrapping.",
          art: "linear-gradient(45deg, #42233f, #151d2d 48%, #ff8fab 49% 52%, #101624 53%)",
        },
      ];

      const html = String.raw;

      function Header() {
        return html`
          <header class="site-header">
            <div class="page-shell header-inner">
              <a class="brand" href="#main-content" aria-label="Nocturne Supply Co. home">
                <span class="brand-mark" aria-hidden="true">N</span>
                <span class="brand-name">Nocturne Supply Co.</span>
              </a>
              <button class="nav-toggle" type="button" aria-expanded="false" aria-controls="primary-navigation">
                Menu
              </button>
              <nav class="primary-nav" id="primary-navigation" aria-label="Primary navigation">
                <ul>
                  <li><a href="#featured">Featured</a></li>
                  <li><a href="#deals">Deals</a></li>
                  <li><a href="#editorial">Editorial</a></li>
                  <li><a href="#newsletter">Rewards</a></li>
                </ul>
              </nav>
              <div class="utility-nav" aria-label="Shopping actions">
                <a class="utility-link" href="#newsletter">Join</a>
                <button class="cart-button" type="button">
                  Cart <span class="cart-count" aria-live="polite">0</span>
                </button>
              </div>
            </div>
          </header>
        `;
      }

      function Hero() {
        return html`
          <section class="hero" aria-labelledby="hero-title">
            <div class="hero-copy">
              <span class="eyebrow">New season edit</span>
              <h1 id="hero-title">Retail after dark.</h1>
              <p>
                Elevated essentials, sculptural accessories, and limited-run drops
                curated for a sharper everyday uniform.
              </p>
              <div class="hero-actions">
                <a class="button button-primary" href="#featured">Shop featured products</a>
                <a class="button button-secondary" href="#editorial">Read the editorial</a>
              </div>
            </div>
            <div class="hero-panel" aria-label="Featured deal preview">
              <div class="showcase">
                <div class="showcase-card">
                  <span class="tag">Limited drop</span>
                  <h2>Carbon Weekender</h2>
                  <p class="card-copy">Weather-ready texture, brushed metal hardware, and cabin-size capacity.</p>
                  <div class="price-row">
                    <span class="price">$128</span>
                    <span class="old-price">$176</span>
                  </div>
                </div>
              </div>
            </div>
          </section>
        `;
      }

      function ProductCard(product) {
        return html`
          <article class="product-card">
            <div class="product-art" aria-hidden="true">
              <span class="product-orb" style="--orb: ${product.orb}"></span>
            </div>
            <div class="product-body">
              <div class="product-meta">
                <span class="category">${product.category}</span>
                <span class="rating" aria-label="Rated ${product.rating} out of 5">★ ${product.rating}</span>
              </div>
              <h3>${product.name}</h3>
              <p class="card-copy">${product.price} · ships in recycled packaging</p>
              <button class="button button-secondary add-to-cart" type="button" aria-label="Add to cart: ${product.name}">
                Add to cart
              </button>
            </div>
          </article>
        `;
      }

      function FeaturedProducts() {
        return html`
          <section id="featured" aria-labelledby="featured-title">
            <div class="section-header">
              <div>
                <span class="eyebrow">Featured products</span>
                <h2 id="featured-title">The current essentials</h2>
                <p class="section-intro">
                  High-impact staples selected for comfort, durability, and night-out polish.
                </p>
              </div>
              <a class="button button-secondary" href="#newsletter">Get drop alerts</a>
            </div>
            <div class="product-grid">
              ${products.map(ProductCard).join("")}
            </div>
          </section>
        `;
      }

      function Deals() {
        return html`
          <section id="deals" aria-labelledby="deals-title">
            <div class="section-header">
              <div>
                <span class="eyebrow">Deals</span>
                <h2 id="deals-title">Weekend price cuts</h2>
                <p class="section-intro">
                  Time-limited offers on the pieces our stylists keep recommending.
                </p>
              </div>
            </div>
            <div class="deal-grid">
              <article class="deal-card featured">
                <div>
                  <span class="timer">Ends Sunday at midnight</span>
                  <h3>30% off travel layers</h3>
                  <p class="deal-copy">
                    Packable puffers, soft-shell overshirts, and merino hoodies built for changing forecasts.
                  </p>
                  <a class="button button-primary" href="#featured">Shop the travel layer deal</a>
                </div>
                <div class="deal-visual" aria-hidden="true"></div>
              </article>
              <div class="deal-stack">
